<?php
require_once '../config/database.php';require_once '../config/helpers.php';
if(empty($_SESSION['user_id'])||($_SESSION['role']??'')!=='student'){header('Location: ../index.php');exit;}
$id=(int)$_SESSION['user_id'];$stmt=mysqli_prepare($conn,'SELECT student_no,full_name,username FROM users WHERE id=? AND role=\'student\'');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$student){header('Location: ../logout.php');exit;}
$stmt=mysqli_prepare($conn,'SELECT s.subject_code,s.subject_name,s.units FROM subjects s JOIN enrollments e ON e.subject_id=s.id WHERE e.student_id=? ORDER BY s.subject_code');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$subjects=mysqli_stmt_get_result($stmt);$count=mysqli_num_rows($subjects);$totalUnits=0;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My portal · Clark College Science of Technology</title><link href="../assets/vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><nav class="navbar"><div class="container app-container"><a class="navbar-brand d-flex align-items-center gap-2" href="dashboard.php"><img class="school-logo school-logo-nav" src="../assets/images/school-logo.jpg" alt="Clark College of Science and Technology logo"> Clark College Science of Technology</a><div class="ms-auto d-flex align-items-center gap-3"><span class="text-muted d-none d-sm-inline"><?=e($student['full_name'])?></span><a class="btn btn-light btn-sm" href="../logout.php">Sign out</a></div></div></nav><main class="container app-container pb-5"><div class="page-head"><div><p class="eyebrow">STUDENT PORTAL</p><h2>Welcome back, <?=e(explode(' ',$student['full_name'])[0])?>.</h2><p class="subheading">Here is your student profile and current subject enrollment.</p></div></div><div class="row g-3 mb-4"><div class="col-md-8"><section class="card h-100"><div class="card-body d-flex align-items-center gap-3"><span class="brand-mark"><?=e(strtoupper(substr($student['full_name'],0,1)))?></span><div><span class="eyebrow">YOUR PROFILE</span><h3 class="mb-1"><?=e($student['full_name'])?></h3><div class="text-muted">Student number: <?=e($student['student_no']?:'Not assigned')?></div><div class="text-muted">Username: <?=e($student['username'])?></div></div></div></section></div><div class="col-md-4"><section class="card stat-card h-100"><div class="d-flex justify-content-between"><span class="stat-label">Enrolled subjects</span><span class="stat-icon">▤</span></div><div class="stat-value"><?=$count?></div><span class="text-muted small">Total units: <?php mysqli_data_seek($subjects,0);while($tmp=mysqli_fetch_assoc($subjects))$totalUnits+=(int)$tmp['units'];echo $totalUnits;?></span></section></div></div><section class="card"><div class="card-header"><h3 class="mb-1">My subjects</h3><span class="small text-muted">Your current subject enrollment list</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Subject code</th><th>Subject name</th><th>Units</th></tr></thead><tbody><?php mysqli_data_seek($subjects,0);if($count):while($s=mysqli_fetch_assoc($subjects)):?><tr><td><span class="badge text-bg-light"><?=e($s['subject_code'])?></span></td><td><strong><?=e($s['subject_name'])?></strong></td><td><?=(int)$s['units']?></td></tr><?php endwhile;else:?><tr><td colspan="3"><div class="empty-state"><strong>No subjects enrolled</strong>Contact your school administrator if you believe this is incorrect.</div></td></tr><?php endif;?></tbody></table></div></section><div class="footer-note">For corrections to your student record or enrollment, contact the school administrator.</div></main></body></html>
